"use client"

import { useMemo, useState } from "react"
import type { ComponentProps, ReactNode } from "react"
import { flexRender, useTable } from "@tanstack/react-table"
import type { Header, RowData, SortingState } from "@tanstack/react-table"
import { ChevronDown, ChevronUp, ChevronsUpDown } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { cn } from "@/lib/utils"
import type {
  DataTableColumnDef,
  FilterableColumn,
} from "@/hoogin/ui/data-table/data-table.types"
import { dataTableFeatures } from "@/hoogin/ui/data-table/data-table.types"
import { DataTablePagination } from "@/hoogin/ui/data-table/data-table-pagination"
import {
  DataTableToolbar,
  type FacetedFilter,
  type GlobalFilterValue,
} from "@/hoogin/ui/data-table/data-table-toolbar"

export type DataTableProps<TData extends RowData, TValue> = {
  columns: DataTableColumnDef<TData, TValue>[]
  data: TData[]
  filterPlaceholder?: string
  filterableColumns?: FilterableColumn[]
  filters?: FacetedFilter[]
  initialSorting?: SortingState
  initialPageSize?: number
  pageSizeOptions?: number[]
  enableRowSelection?: boolean
  getRowId?: (row: TData) => string
  emptyState?: ReactNode
  className?: string
  tableProps?: ComponentProps<typeof Table>
}

function DataTable<TData extends RowData, TValue>({
  columns,
  data,
  filterPlaceholder,
  filterableColumns,
  filters,
  initialSorting,
  initialPageSize = 10,
  pageSizeOptions,
  enableRowSelection = false,
  getRowId,
  emptyState,
  className,
  tableProps,
}: DataTableProps<TData, TValue>) {
  const [sorting, setSorting] = useState<SortingState>(initialSorting ?? [])
  const [globalFilter, setGlobalFilter] = useState<GlobalFilterValue>({
    value: "",
    columns: [],
  })

  const selectionColumn = useMemo<DataTableColumnDef<TData, unknown>>(
    () => ({
      id: "select",
      enableSorting: false,
      enableHiding: false,
      header: ({ table }) => (
        <Checkbox
          checked={table.getIsAllPageRowsSelected()}
          indeterminate={
            table.getIsSomePageRowsSelected() &&
            !table.getIsAllPageRowsSelected()
          }
          onCheckedChange={(value) => table.toggleAllPageRowsSelected(!!value)}
          aria-label="Select all rows"
        />
      ),
      cell: ({ row }) => (
        <Checkbox
          checked={row.getIsSelected()}
          onCheckedChange={(value) => row.toggleSelected(!!value)}
          disabled={!row.getCanSelect()}
          aria-label="Select row"
        />
      ),
    }),
    []
  )

  // ponytail: cast needed because v9 Column<TValue> is invariant; display
  // column has no accessor so the value type is irrelevant here.
  const allColumns = useMemo(
    () =>
      (enableRowSelection ? [selectionColumn, ...columns] : columns) as DataTableColumnDef<TData>[],
    [enableRowSelection, selectionColumn, columns]
  )

  const table = useTable({
    features: dataTableFeatures,
    data,
    columns: allColumns,
    getRowId,
    state: { sorting, globalFilter },
    onSortingChange: setSorting,
    onGlobalFilterChange: setGlobalFilter,
    globalFilterFn: (row, _columnId, filterValue) => {
      const filter = (filterValue as GlobalFilterValue | undefined) ?? {
        value: "",
        columns: [],
      }
      if (!filter.value) return true
      const query = filter.value.toLowerCase()
      const cells = row
        .getAllCells()
        .filter((cell) => cell.column.getCanGlobalFilter())
        .filter(
          (cell) =>
            !filterableColumns ||
            filterableColumns.some((filterable) => filterable.column === cell.column.id)
        )
      const targets =
        filter.columns.length > 0
          ? cells.filter((cell) => filter.columns.includes(cell.column.id))
          : cells
      return targets.some((cell) =>
        String(cell.getValue() ?? "").toLowerCase().includes(query)
      )
    },
    initialState: {
      sorting: initialSorting,
      pagination: { pageIndex: 0, pageSize: initialPageSize },
    },
    enableRowSelection,
  })

  return (
    <div className={cn("w-full space-y-3", className)}>
      <DataTableToolbar
        table={table}
        filterableColumns={filterableColumns}
        filters={filters}
        placeholder={filterPlaceholder}
      />
      <div className="rounded-lg border">
        <Table {...tableProps}>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead key={header.id} colSpan={header.colSpan}>
                    {header.isPlaceholder ? null : (
                      <DataTableColumnHeader header={header} />
                    )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && "selected"}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={table.getVisibleLeafColumns().length}
                  className="h-24 text-center text-muted-foreground"
                >
                  {emptyState ?? "No results."}
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <DataTablePagination
        table={table}
        pageSizeOptions={pageSizeOptions}
        showSelectedCount={enableRowSelection}
      />
    </div>
  )
}

function DataTableColumnHeader<TData extends RowData, TValue>({
  header,
  className,
}: {
  header: Header<typeof dataTableFeatures, TData, TValue>
  className?: string
}) {
  if (!header.column.getCanSort()) {
    return (
      <div className={cn("text-left font-medium", className)}>
        {flexRender(header.column.columnDef.header, header.getContext())}
      </div>
    )
  }

  const label = flexRender(
    header.column.columnDef.header,
    header.getContext()
  )
  const sorted = header.column.getIsSorted()

  return (
    <Button
      variant="ghost"
      size="sm"
      className={cn(
        "-ml-2 h-8 select-none text-left hover:bg-transparent",
        className
      )}
      onClick={header.column.getToggleSortingHandler()}
    >
      {label}
      {sorted === "asc" ? (
        <ChevronUp className="size-4" />
      ) : sorted === "desc" ? (
        <ChevronDown className="size-4" />
      ) : (
        <ChevronsUpDown className="size-4 opacity-60" />
      )}
    </Button>
  )
}

export { DataTable }

"use client"

import type { ReactTable, RowData } from "@tanstack/react-table"
import { X } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  DataTableFacetedFilter,
  type FacetedOption,
} from "@/hoogin/ui/data-table/data-table-faceted-filter"
import { DataTableViewOptions } from "@/hoogin/ui/data-table/data-table-view-options"
import type { FilterableColumn } from "@/hoogin/ui/data-table/data-table.types"
import { dataTableFeatures } from "@/hoogin/ui/data-table/data-table.types"

export type GlobalFilterValue = {
  value: string
  columns: string[]
}

export type FacetedFilter = {
  columnId: string
  title: string
  options: FacetedOption[]
}

const ALL_COLUMNS = "__all__"

type DataTableToolbarProps<TData extends RowData> = {
  table: ReactTable<typeof dataTableFeatures, TData>
  filterableColumns?: FilterableColumn[]
  filters?: FacetedFilter[]
  placeholder?: string
}

function DataTableToolbar<TData extends RowData>({
  table,
  filterableColumns,
  filters,
  placeholder = "Filter...",
}: DataTableToolbarProps<TData>) {
  const filter = (table.state.globalFilter as GlobalFilterValue | undefined) ?? {
    value: "",
    columns: [],
  }

  const columns = table
    .getAllLeafColumns()
    .filter((column) => column.getCanGlobalFilter() && column.getIsVisible())
    .filter((column) =>
      !filterableColumns ||
      filterableColumns.some((filterable) => filterable.column === column.id)
    )
    .map((column) => ({
      id: column.id,
      caption:
        filterableColumns?.find((filterable) => filterable.column === column.id)
          ?.caption ?? column.id,
    }))

  const filterValue = filter.columns.length > 0 ? filter.columns[0] : ALL_COLUMNS

  const items = [
    { value: ALL_COLUMNS, label: "Search columns", optionLabel: "All columns" },
    ...columns.map((column) => ({
      value: column.id,
      label: column.caption,
      optionLabel: column.caption,
    })),
  ]

  function updateFilter(next: GlobalFilterValue) {
    table.setGlobalFilter(next)
  }

  function handleColumnChange(value: string | null) {
    updateFilter({ ...filter, columns: value && value !== ALL_COLUMNS ? [value] : [] })
  }

  const hasFacetedSelection =
    filters?.some((filter) => {
      const value = table.getColumn(filter.columnId)?.getFilterValue()
      return Array.isArray(value) && value.length > 0
    }) ?? false

  const showReset =
    filter.value.length > 0 || filter.columns.length > 0 || hasFacetedSelection

  function resetFilters() {
    updateFilter({ value: "", columns: [] })
    filters?.forEach((filter) => {
      table.getColumn(filter.columnId)?.setFilterValue([])
    })
  }

  return (
    <div className="flex flex-col gap-3">
      {filters && filters.length > 0 ? (
        <div className="flex flex-wrap items-center gap-2">
          {filters.map((filter) => {
            const column = table.getColumn(filter.columnId)
            if (!column) return null
            return (
              <DataTableFacetedFilter
                key={filter.columnId}
                columnId={filter.columnId}
                column={column}
                title={filter.title}
                options={filter.options}
              />
            )
          })}
        </div>
      ) : null}
      <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
        <div className="flex flex-wrap items-center gap-2">
          {columns.length > 1 ? (
            <Select value={filterValue} onValueChange={handleColumnChange} items={items}>
              <SelectTrigger className="h-8 w-36" aria-label="Search in columns">
                <SelectValue />
              </SelectTrigger>
              <SelectContent align="start">
                <SelectGroup>
                  {items.map((item) => (
                    <SelectItem key={item.value} value={item.value} label={item.label}>
                      {item.optionLabel}
                    </SelectItem>
                  ))}
                </SelectGroup>
              </SelectContent>
            </Select>
          ) : null}
          <Input
            value={filter.value}
            onChange={(event) => updateFilter({ ...filter, value: event.target.value })}
            placeholder={placeholder}
            aria-label="Filter"
            className="h-8 w-48 sm:w-64"
          />
          {showReset ? (
            <Button
              variant="outline"
              size="sm"
              className="h-8 w-8 p-0"
              onClick={resetFilters}
              aria-label="Reset filters"
            >
              <X className="size-4" />
            </Button>
          ) : null}
        </div>
        <DataTableViewOptions table={table} />
      </div>
    </div>
  )
}

export { DataTableToolbar }
